INSERT INTO auth.users(id,email) VALUES ('96000000-0000-4000-8000-000000000001','quotation-admin@example.invalid'),('96000000-0000-4000-8000-000000000002','quotation-cashier@example.invalid');
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
