SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"96000000-0000-4000-8000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT public.save_customer('{"display_name":"Original master","contact_name":"Quoted contact","phone":"0501234567","vat_applicable":false,"billing_name":"Original billing"}','96000000-0000-4000-8000-000000000010',NULL);
