SELECT extensions.is(current_setting('test.q')::jsonb->>'vat_applicable','false','explicit customer exemption captured');
SELECT extensions.is(public.save_quotation('96000000-0000-4000-8000-000000000011',NULL,0,current_setting('test.data')::jsonb,'96000000-0000-4000-8000-000000000010',1,false),current_setting('test.q')::jsonb,'exact request replay');
SELECT extensions.throws_ok($$SELECT public.save_quotation('96000000-0000-4000-8000-000000000011',NULL,0,'{}',NULL,NULL,false)$$,'PT409','quotation_request_conflict','changed request UUID rejected');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb||'{"final_price":1}',NULL,NULL,false)$$,'22023','invalid_quotation_fields','browser totals forbidden');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb||'{"vat_applicable":true}',NULL,NULL,false)$$,'22023','invalid_quotation_fields','caller VAT forbidden');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,jsonb_set(current_setting('test.data')::jsonb,'{selected_activities,0,quantity}','-1'),NULL,NULL,false)$$,'22023','invalid_quotation_item','negative quantity rejected');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,jsonb_set(current_setting('test.data')::jsonb,'{selected_activities,0,price_per_person}','1.001'),NULL,NULL,false)$$,'22023','invalid_quotation_item','money precision rejected');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb||'{"discount":999}',NULL,NULL,false)$$,'22023','invalid_quotation_discount','discount cannot exceed gross');
SELECT extensions.throws_ok($$UPDATE public.quotes SET final_price=1 WHERE id=(current_setting('test.q')::jsonb->>'id')::uuid$$,'42501',NULL,'direct quote mutation denied');
SELECT public.save_customer('{"display_name":"Changed master","contact_name":"Changed master","vat_applicable":true,"billing_name":"Changed billing"}','96000000-0000-4000-8000-000000000010',1);
SELECT set_config('test.q2',public.save_quotation('96000000-0000-4000-8000-000000000012',(current_setting('test.q')::jsonb->>'id')::uuid,1,current_setting('test.data')::jsonb||'{"notes":"Revision two"}','96000000-0000-4000-8000-000000000010',1,false)::text,true);
SELECT extensions.is(current_setting('test.q2')::jsonb->>'vat_applicable','false','ordinary edit preserves customer VAT after master changes');
SELECT extensions.is((current_setting('test.q2')::jsonb->>'customer_version')::integer,1,'ordinary edit preserves quoted customer version');
SELECT extensions.is(public.save_quotation('96000000-0000-4000-8000-000000000011',NULL,0,current_setting('test.data')::jsonb,'96000000-0000-4000-8000-000000000010',1,false),current_setting('test.q')::jsonb,'old request replays old result after later revision');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),(current_setting('test.q')::jsonb->>'id')::uuid,1,current_setting('test.data')::jsonb,'96000000-0000-4000-8000-000000000010',1,false)$$,'PT409','quotation_version_conflict','stale quote edit rejected');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),(current_setting('test.q')::jsonb->>'id')::uuid,2,current_setting('test.data')::jsonb,'96000000-0000-4000-8000-000000000010',1,true)$$,'PT409','quotation_customer_version_conflict','stale explicit customer refresh rejected');
SELECT set_config('test.o',public.convert_quotation_to_order((current_setting('test.q2')::jsonb->>'id')::uuid,2)::text,true);
SELECT extensions.is((current_setting('test.o')::jsonb->>'total_price')::numeric,50.00::numeric,'order preserves discounted gross total');
SELECT extensions.is(current_setting('test.o')::jsonb->>'status',U&'\05DE\05D0\05D5\05E9\05E8','converted order retains normal approved status');
SELECT extensions.is(current_setting('test.o')::jsonb->>'payment_status',U&'\05DC\05D0 \05E9\05D5\05DC\05DD','converted order is unpaid');
