SELECT extensions.is(current_setting('test.o')::jsonb->>'vat_applicable','false','conversion takes quoted VAT not changed master');
SELECT extensions.is(current_setting('test.o')::jsonb->>'billing_institution_name','Quoted billing','conversion preserves manual billing override');
SELECT extensions.is((SELECT customer_version FROM public.customer_snapshots WHERE id=(current_setting('test.o')::jsonb->>'customer_snapshot_id')::uuid),1,'canonical order customer snapshot uses quoted customer version');
SELECT extensions.is(public.convert_quotation_to_order((current_setting('test.q2')::jsonb->>'id')::uuid,2)->>'id',current_setting('test.o')::jsonb->>'id','conversion exact existing order replay');
SELECT extensions.is((SELECT count(*) FROM public.orders WHERE quote_id=(current_setting('test.q')::jsonb->>'id')::uuid),1::bigint,'one order per quote');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),(current_setting('test.q')::jsonb->>'id')::uuid,2,current_setting('test.data')::jsonb,NULL,NULL,false)$$,'PT409','quotation_already_converted','converted quote cannot be rewritten');
SELECT extensions.throws_ok($$UPDATE public.orders SET quotation_snapshot='{}' WHERE id=(current_setting('test.o')::jsonb->>'id')::uuid$$,'42501','quotation_order_snapshot_immutable','order quoted contents immutable');
SELECT extensions.throws_ok($$UPDATE public.quotation_revisions SET data='{}'$$,'42501',NULL,'revision history cannot be directly edited');
SELECT set_config('test.legacy',public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb,NULL,NULL,false)::text,true);
SELECT extensions.is(current_setting('test.legacy')::jsonb->'vat_applicable','null'::jsonb,'manual unlinked VAT unknown');
SELECT set_config('test.legacy_order',public.convert_quotation_to_order((current_setting('test.legacy')::jsonb->>'id')::uuid,1)::text,true);
SELECT extensions.is(current_setting('test.legacy_order')::jsonb->'customer_snapshot_id','null'::jsonb,'manual legacy conversion stays unlinked');
INSERT INTO public.activities(id,name,price_per_person) VALUES ('96000000-0000-4000-8000-000000000031','Catalog activity one',12.35),('96000000-0000-4000-8000-000000000032','Catalog activity two',7.5);
SELECT set_config('test.activity_items','[{"item_type":"activity","activity_id":"96000000-0000-4000-8000-000000000031","activity_name":"Quoted activity one","price_per_person":12.35,"quantity":3,"description":"Quoted description"}]',true);
SELECT set_config('test.single_activity',public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb||jsonb_build_object('selected_activities',current_setting('test.activity_items')::jsonb),NULL,NULL,false)::text,true);
UPDATE public.activities SET name='Changed catalog name',price_per_person=999 WHERE id='96000000-0000-4000-8000-000000000031';
SELECT set_config('test.single_activity_order',public.convert_quotation_to_order((current_setting('test.single_activity')::jsonb->>'id')::uuid,1)::text,true);
SELECT extensions.is(current_setting('test.single_activity_order')::jsonb->>'activity_id','96000000-0000-4000-8000-000000000031','single activity conversion preserves valid compatibility FK');
SELECT extensions.is((current_setting('test.single_activity_order')::jsonb->>'total_price')::numeric,35.00::numeric,'single activity conversion preserves quoted quantity and discount after catalog edit');
SELECT extensions.is(current_setting('test.single_activity_order')::jsonb->'quotation_snapshot'->'selected_activities'->0->>'activity_name','Quoted activity one','single activity snapshot never enriches from changed catalog');
SELECT extensions.is((current_setting('test.single_activity_order')::jsonb->'quotation_snapshot'->'selected_activities'->0->>'quantity')::numeric,3::numeric,'single activity explicit quantity is independent of participants');
SELECT set_config('test.multi_activity',public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb||jsonb_build_object('selected_activities',current_setting('test.activity_items')::jsonb||'[{"item_type":"activity","activity_id":"96000000-0000-4000-8000-000000000032","activity_name":"Quoted activity two","price_per_person":7.5,"quantity":2}]'::jsonb),NULL,NULL,false)::text,true);
SELECT set_config('test.multi_activity_order',public.convert_quotation_to_order((current_setting('test.multi_activity')::jsonb->>'id')::uuid,1)::text,true);
SELECT extensions.is(current_setting('test.multi_activity_order')::jsonb->'activity_id','null'::jsonb,'multiple activities never pretend a single activity is the complete order');
SELECT extensions.is((current_setting('test.multi_activity_order')::jsonb->>'total_price')::numeric,50.00::numeric,'multiple activity-only total includes all quantities and discount');
SELECT extensions.is(current_setting('test.multi_activity_order')::jsonb->'quotation_snapshot'->'selected_activities',current_setting('test.multi_activity')::jsonb->'selected_activities','all activity-only items survive conversion exactly');
SELECT extensions.is(public.convert_quotation_to_order((current_setting('test.multi_activity')::jsonb->>'id')::uuid,1)->>'id',current_setting('test.multi_activity_order')::jsonb->>'id','activity-only conversion replay is idempotent');
SELECT extensions.is((SELECT count(*) FROM public.sales),0::bigint,'conversion creates no sales');
SELECT extensions.is((SELECT count(*) FROM public.payment_transactions),0::bigint,'conversion creates no payments');
SELECT extensions.is((SELECT count(*) FROM public.accounting_events),0::bigint,'conversion creates no accounting events');
SELECT extensions.is((SELECT quotation_version FROM public.quotes WHERE id='96000000-0000-4000-8000-000000000090'),0,'old quotes are not backfilled');
SELECT extensions.throws_ok($$SELECT public.convert_quotation_to_order('96000000-0000-4000-8000-000000000090',0)$$,'PT409','quotation_save_revision_required','legacy conversion explicitly requires saved revision');
SELECT set_config('test.saved_legacy',public.save_quotation(pg_catalog.gen_random_uuid(),'96000000-0000-4000-8000-000000000090',0,'{}',NULL,NULL,false)::text,true);
