SELECT extensions.is(current_setting('test.refreshed')::jsonb->>'client_name','Changed master','explicit refresh uses current master contact unless overridden');
INSERT INTO public.orders(client_name,client_phone,activity_date,num_participants,quote_id) VALUES('Manual linked order','0500000000','2026-11-01',1,(current_setting('test.refresh')::jsonb->>'id')::uuid);
SELECT extensions.throws_ok($$SELECT public.convert_quotation_to_order((current_setting('test.refreshed')::jsonb->>'id')::uuid,2)$$,'PT409','quotation_order_link_conflict','manual order link with missing converted pointer conflicts safely');
SELECT extensions.throws_ok($$INSERT INTO public.orders(client_name,client_phone,activity_date,num_participants,quote_id) VALUES('Duplicate','0500000000','2026-11-01',1,(current_setting('test.refresh')::jsonb->>'id')::uuid)$$,'23505',NULL,'unique index prevents racing duplicate link');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,jsonb_set(current_setting('test.data')::jsonb,'{selected_activities,0,quantity}','null'),NULL,NULL,false)$$,'22023','invalid_quotation_item','explicit null quantity rejected rather than fallback');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,jsonb_set(current_setting('test.data')::jsonb,'{selected_activities,0,images}','{}'),NULL,NULL,false)$$,'22023','invalid_quotation_item','malformed historical media rejected explicitly');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,jsonb_set(current_setting('test.data')::jsonb,'{selected_activities,0,price_per_person}','99999999.99'),NULL,NULL,false)$$,'22023','invalid_quotation_total','unrepresentable line total rejected');
SELECT set_config('test.cancelled',public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb||jsonb_build_object('status',U&'\05D1\05D5\05D8\05DC\05D4'),NULL,NULL,false)::text,true);
SELECT extensions.throws_ok($$SELECT public.convert_quotation_to_order((current_setting('test.cancelled')::jsonb->>'id')::uuid,1)$$,'PT409','quotation_cancelled','cancelled quotation cannot convert');
-- Force deferred revision checks before rollback so the rehearsal exercises them.
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"96000000-0000-4000-8000-000000000002"}',true);
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb,NULL,NULL,false)$$,'42501','quotation_access_denied','cashier cannot save quotation');
SELECT extensions.throws_ok($$SELECT public.convert_quotation_to_order((current_setting('test.q')::jsonb->>'id')::uuid,2)$$,'42501','quotation_access_denied','cashier cannot convert quotation');
SELECT extensions.is((SELECT count(*) FROM public.quotation_revisions),0::bigint,'cashier cannot read quotation revisions');
RESET ROLE;
INSERT INTO auth.users(id,email) VALUES ('96000000-0000-4000-8000-000000000020','quotation-instructor@example.invalid'),('96000000-0000-4000-8000-000000000021','quotation-operations@example.invalid');
INSERT INTO public.instructors(id,full_name,phone,email) VALUES ('96000000-0000-4000-8000-000000000022','Quotation instructor','0500000000','quotation-instructor@example.invalid');
INSERT INTO public.orders(id,client_name,client_phone,activity_date,num_participants,instructor_id) VALUES ('96000000-0000-4000-8000-000000000023','Assigned ordinary order','0500000000','2026-11-01',1,'96000000-0000-4000-8000-000000000022');
UPDATE public.orders SET instructor_id='96000000-0000-4000-8000-000000000022' WHERE id=(current_setting('test.o')::jsonb->>'id')::uuid;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
UPDATE public.profiles SET role='operations' WHERE id='96000000-0000-4000-8000-000000000021';
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"96000000-0000-4000-8000-000000000020"}',true);
SET LOCAL ROLE authenticated;
SELECT extensions.is((SELECT count(*) FROM public.quotes),1::bigint,'instructor sees only the correctly correlated linked quote');
SELECT extensions.is((SELECT id FROM public.quotes),(current_setting('test.q')::jsonb->>'id')::uuid,'instructor policy correlates orders.quote_id with outer quote id');
SELECT extensions.is((SELECT count(*) FROM public.quotation_revisions),0::bigint,'instructor gains no revision billing access');
SELECT extensions.throws_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb,NULL,NULL,false)$$,'42501','quotation_access_denied','instructor cannot save quotations');
SELECT extensions.throws_ok($$UPDATE public.orders SET quote_id=(current_setting('test.cancelled')::jsonb->>'id')::uuid WHERE id='96000000-0000-4000-8000-000000000023'$$,'42501','quotation_link_access_denied','instructor cannot steal unrelated quote visibility through ordinary assigned order');
SELECT extensions.is((SELECT count(*) FROM public.quotes),1::bigint,'failed instructor relink grants no additional quote visibility');
SELECT extensions.lives_ok($$UPDATE public.orders SET instructor_notified=true WHERE id='96000000-0000-4000-8000-000000000023'$$,'instructor notification update remains allowed');
SELECT extensions.is((SELECT instructor_notified FROM public.orders WHERE id='96000000-0000-4000-8000-000000000023'),true,'instructor notification change persists within test transaction');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"96000000-0000-4000-8000-000000000002"}',true);
SELECT extensions.throws_ok($$UPDATE public.orders SET quote_id=(current_setting('test.cancelled')::jsonb->>'id')::uuid WHERE id='96000000-0000-4000-8000-000000000023'$$,'42501','quotation_link_access_denied','cashier cannot relink existing order to quotation');
SELECT extensions.throws_ok($$INSERT INTO public.orders(client_name,client_phone,activity_date,num_participants,quote_id) VALUES('Forbidden cashier link','0500000000','2026-11-01',1,(current_setting('test.cancelled')::jsonb->>'id')::uuid)$$,'42501','quotation_link_access_denied','cashier cannot create an order with a quotation link');
SELECT extensions.throws_ok($$UPDATE public.orders SET quotation_snapshot='{}' WHERE id='96000000-0000-4000-8000-000000000023'$$,'42501','quotation_link_access_denied','cashier cannot inject a quotation snapshot into ordinary order');
SELECT extensions.lives_ok($$UPDATE public.orders SET notes='Ordinary cashier edit' WHERE id='96000000-0000-4000-8000-000000000023'$$,'ordinary cashier order edits retain existing permissions');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"96000000-0000-4000-8000-000000000021"}',true);
SELECT extensions.lives_ok($$SELECT public.save_quotation(pg_catalog.gen_random_uuid(),NULL,0,current_setting('test.data')::jsonb,NULL,NULL,false)$$,'operations can save quotations');
SELECT extensions.lives_ok($$UPDATE public.orders SET quote_id=(current_setting('test.cancelled')::jsonb->>'id')::uuid WHERE id='96000000-0000-4000-8000-000000000023'$$,'operations can explicitly associate an ordinary order with a quotation');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SET LOCAL ROLE service_role;
SELECT extensions.lives_ok($$UPDATE public.orders SET notes=notes WHERE id=(current_setting('test.o')::jsonb->>'id')::uuid$$,'service-role order update with unchanged quotation linkage remains allowed');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"96000000-0000-4000-8000-000000000021"}',true);
SET LOCAL ROLE authenticated;
SET CONSTRAINTS ALL IMMEDIATE;
RESET ROLE;
SELECT extensions.throws_ok($$INSERT INTO public.quotes(client_name,client_phone,final_price) VALUES('Forged direct quote','0500000000',1)$$,'42501','quotation_revision_required','trigger prevents owner-level insertion without authoritative revision');
SELECT extensions.throws_ok($$UPDATE public.quotation_revisions SET data='{}'$$,'42501','quotation_artifact_immutable','revision mutation trigger protects privileged paths');
SET LOCAL ROLE anon;
SELECT extensions.throws_ok($$SELECT public.convert_quotation_to_order((current_setting('test.q')::jsonb->>'id')::uuid,2)$$,'42501',NULL,'anonymous role has no conversion execute grant');
RESET ROLE;
SELECT * FROM extensions.finish();
ROLLBACK;
